<?php
$root=dirname(__DIR__);if(getenv('GAME2_DATABASE_CONFIG')===false||getenv('GAME2_DATABASE_CONFIG')==='')putenv('GAME2_DATABASE_CONFIG='.$root.'/config/database.test.php.example');require_once $root.'/app/bootstrap.php';require_once $root.'/app/MigrationService.php';require_once $root.'/app/BehaviorService.php';require_once $root.'/app/CausalService.php';require_once $root.'/app/ConsequencePropagationService.php';require_once $root.'/app/DynamicOpportunityService.php';require_once $root.'/app/StateSyncService.php';require_once $root.'/app/SimulationService.php';require_once __DIR__.'/SimulationHarness.php';
$args=$argv;array_shift($args);$opt=['plot'=>'EMPTY_THRONE','runs'=>10,'strategy'=>'no-action','duration'=>300,'step'=>30,'reset'=>false,'json'=>false];foreach($args as$a){if($a==='--reset'){$opt['reset']=true;continue;}if($a==='--json'){$opt['json']=true;continue;}if(preg_match('/^--([^=]+)=(.*)$/',$a,$m)){$k=$m[1];$v=$m[2];if(array_key_exists($k,$opt))$opt[$k]=in_array($k,['runs','duration','step'],true)?(int)$v:$v;}}
$strategies=['no-action','random','first','anti-rowan','pro-rowan'];if(!in_array($opt['strategy'],$strategies,true)){fwrite(STDERR,'Strategy must be '.implode(', ',$strategies).".\n");exit(2);}if((int)$opt['runs']<1){fwrite(STDERR,"--runs must be at least 1.\n");exit(2);}
try{if($opt['reset'])SimulationHarness::resetDatabase();else MigrationService::run();$results=[];$outcomes=[];$familyLabels=[];$warningCount=0;$factorRanges=[];$totals=['player_actions'=>0,'npc_actions'=>0,'player_no_action'=>0];for($i=1;$i<=(int)$opt['runs'];$i++){$r=SimulationHarness::run((string)$opt['plot'],(string)$opt['strategy'],(int)$opt['duration'],(int)$opt['step']);$results[]=$r;$sig=$r['outcome_signature'];$outcomes[$sig]=($outcomes[$sig]??0)+1;$familyLabels[$sig]=$r['outcome_family_label'];$warningCount+=count($r['warnings']);foreach($r['counts']as$k=>$v)$totals[$k]+=$v;foreach($r['factors']as$k=>$v){if(!isset($factorRanges[$k]))$factorRanges[$k]=['min'=>$v,'max'=>$v];else{$factorRanges[$k]['min']=min($factorRanges[$k]['min'],$v);$factorRanges[$k]['max']=max($factorRanges[$k]['max'],$v);}}}arsort($outcomes);$families=[];foreach($outcomes as$sig=>$n)$families[]=['signature'=>$sig,'count'=>$n,'percent'=>round($n*100/(int)$opt['runs'],1),'label'=>$familyLabels[$sig]];$summary=['plot'=>$opt['plot'],'runs'=>(int)$opt['runs'],'strategy'=>$opt['strategy'],'unique_outcome_families'=>count($outcomes),'outcome_families'=>$families,'average_counts'=>array_map(fn($v)=>round($v/(int)$opt['runs'],2),$totals),'factor_ranges'=>$factorRanges,'warning_count'=>$warningCount,'runs_detail'=>$results];if($opt['json']){echo json_encode($summary,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE).PHP_EOL;exit($warningCount?1:0);}echo "Game2 simulation batch\nPlot: {$opt['plot']} | Runs: {$opt['runs']} | Strategy: {$opt['strategy']}\nSemantic outcome families: ".count($outcomes)."\n";foreach(array_slice($families,0,15)as$f)echo '  '.$f['count'].' ('.$f['percent'].'%) '.$f['label'].PHP_EOL;echo "Average player actions: {$summary['average_counts']['player_actions']}\nAverage NPC actions: {$summary['average_counts']['npc_actions']}\nAverage player no-actions: {$summary['average_counts']['player_no_action']}\nFactor ranges:\n";foreach($factorRanges as$k=>$range)echo "  {$k}: {$range['min']}..{$range['max']}\n";echo "Integrity warnings: {$warningCount}\n";if($warningCount)foreach($results as$r)foreach($r['warnings']as$w)echo "  Simulation {$r['simulation_id']}: {$w}\n";exit($warningCount?1:0);}catch(Throwable$e){fwrite(STDERR,'Simulation harness failed: '.$e->getMessage().PHP_EOL);exit(1);}
